import { ViewTransition } from 'react'

const directional = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
}

// Wrap each page's content (not the layout) so enter/exit fire on navigation.
// Only navigations tagged with a transition type slide; everything else
// (browser back/forward, refreshes, Suspense reveals) does not.
export function DirectionalTransition({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <ViewTransition enter={directional} exit={directional} default="none">
      {children}
    </ViewTransition>
  )
}

